//! 🔹️ Fixed singleton fields prepare one original sealed child and its enclosing branch without row mirrors.
use crate::{snapshot::{original::EnergyModelSnapshot,state::fields::RetainedBranchProjection},diff::original::EnergyModelDiff,row::{BranchOutput,RowOutcome},scalar::{NativeScalar,CursorClose,cursor_demand,close_cursor,birth,invalid,scalar,nested,child,add,tag,receipt},leaf::RowFieldPreparation};
use semio_framework_value::{RetirementDemand,ValueError,shared_issuance::SealedShared,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use semio_framework_value_snapshot_projection::snapshot_projection::SnapshotProjection;
use protocol::mutation::retained::retained_mutation_demand_fits;
use std::mem::{size_of,ManuallyDrop};
/// 🧭️ Authored scalar and contextual limits name one actual field in its original singleton branch.
pub trait SingleFieldPath:Send+Sync+'static{
 type Scalar:NativeScalar;type Branch:SnapshotProjection<Output:crate::snapshot::state::fields::BranchProjectionOutput<Self::Branch>>+Send+Sync;type Output:BranchOutput<Self::Branch>;
 fn branch(original:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,Self::Branch>;
 fn read(branch:&Self::Branch)->Self::Scalar;fn select(branch:&mut Self::Branch)->&mut Self::Scalar;
 fn valid(value:Self::Scalar)->bool;
 fn valid_context(_:Self::Scalar,_:&Self::Branch)->bool{true}
 fn output()->Self::Output;
}
/// 🧳️ Candidate scalar, displaced original and enclosing output remain independently funded and closeable.
pub struct SingleFieldPreparation<S:SingleFieldPath>{original:Option<RetainedCloneBinding>,authored:Option<RetainedCloneBinding>,stage:Option<Box<RetainedBranchProjection<S::Branch>>>,output:Option<Box<S::Output>>,value:ManuallyDrop<Option<S::Scalar>>,inverse:ManuallyDrop<Option<S::Scalar>>,branch:ManuallyDrop<Option<SealedShared<S::Branch>>>,decision:ManuallyDrop<Option<EnergyModelDiff>>,phase:u8,outcome:Option<RowOutcome>,closing:bool,retirement:RetainedCloneClose}
impl<S:SingleFieldPath> SingleFieldPreparation<S>{
 pub fn new()->Self{Self{original:None,authored:None,stage:None,output:None,value:ManuallyDrop::new(None),inverse:ManuallyDrop::new(None),branch:ManuallyDrop::new(None),decision:ManuallyDrop::new(None),phase:0,outcome:None,closing:false,retirement:Default::default()}}
 pub fn ready(&self)->bool{!self.closing&&self.phase==99}
 pub fn outcome(&self)->Option<RowOutcome>{self.outcome}
 fn check(&self,input:RetainedCloneRef<'_,S::Scalar>,original:RetainedCloneRef<'_,EnergyModelSnapshot>)->Result<(),ValueError>{input.check_binding(&self.authored)?;original.check_binding(&self.original)?;Ok(())}
 pub fn demand(&self,input:RetainedCloneRef<'_,S::Scalar>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>=99{return Err(invalid());}self.check(input,original)?;match self.phase{
  0=>nested(scalar(original.binding_copy_bytes()),1),1=>nested(scalar(input.binding_copy_bytes()),1),2|3|4=>Ok(scalar(2*size_of::<S::Branch>()+2*size_of::<S::Scalar>()+2*size_of::<Option<S::Scalar>>()+3)),5=>Ok(birth::<RetainedBranchProjection<S::Branch>>()),6|8=>nested(self.stage.as_ref().ok_or_else(invalid)?.demand(S::branch(original),body.saturating_sub(1))?,1),7=>nested(RetainedBranchProjection::<S::Branch>::exchange_demand::<S::Scalar>(),1),9=>nested(self.stage.as_ref().ok_or_else(invalid)?.take_demand()?,2*size_of::<Option<SealedShared<S::Branch>>>()+1),10=>cursor_demand(&self.stage,body),11=>Ok(birth::<S::Output>()),12=>nested(self.output.as_ref().ok_or_else(invalid)?.demand(&self.branch,original,body.saturating_sub(1))?,1),13=>nested(self.output.as_ref().ok_or_else(invalid)?.take_demand()?,2*size_of::<Option<EnergyModelDiff>>()+1),14=>cursor_demand(&self.output,body),_=>Err(invalid())}}
 pub fn advance(&mut self,input:RetainedCloneRef<'_,S::Scalar>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(input,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{
  0=>{p=add(original.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=1;},1=>{p=add(input.bind(&mut self.authored,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{if S::valid(*input.get()){self.phase=3;}else{self.outcome=Some(RowOutcome::Invalid);self.phase=99;}},3=>{if S::read(S::branch(original).get())==*input.get(){self.outcome=Some(RowOutcome::Unchanged);self.phase=99;}else{self.phase=4;}},4=>{if S::valid_context(*input.get(),S::branch(original).get()){*self.value=Some(*input.get());self.phase=5;}else{self.outcome=Some(RowOutcome::InvalidContext);self.phase=99;}},5=>{self.stage=Some(Box::new(RetainedBranchProjection::new()));self.phase=6;},6|8=>{let stage=self.stage.as_mut().ok_or_else(invalid)?;p=add(stage.advance(S::branch(original),body.saturating_sub(1),child(g,1)).map_err(|e|tag(e,1))?.progress(),1)?;if self.phase==6&&stage.raw_ready(){self.phase=7;}else if self.phase==8&&stage.ready(){self.phase=9;}},7=>{let stage=self.stage.as_mut().ok_or_else(invalid)?;let(_,progress)=stage.exchange(S::select,&mut self.value,&mut self.inverse,child(g,1)).map_err(|e|tag(e,1))?;stage.begin_seal()?;self.phase=8;p=add(progress,1)?;},9=>{let extra=2*size_of::<Option<SealedShared<S::Branch>>>()+1;let stage=self.stage.as_mut().ok_or_else(invalid)?;let(branch,progress)=stage.take(child(g,extra)).map_err(|e|tag(e,extra))?.ok_or_else(invalid)?;*self.branch=Some(branch);stage.begin_close();self.phase=10;p=add(progress,extra)?;},10=>{p=close_cursor(&mut self.stage,g)?;if self.stage.is_none(){self.phase=11;}},11=>{self.output=Some(Box::new(S::output()));self.phase=12;},12=>{let output=self.output.as_mut().ok_or_else(invalid)?;p=add(output.advance(&mut self.branch,original,body.saturating_sub(1),child(g,1)).map_err(|e|tag(e,1))?.progress(),1)?;if output.ready(){self.phase=13;}},13=>{let extra=2*size_of::<Option<EnergyModelDiff>>()+1;let output=self.output.as_mut().ok_or_else(invalid)?;let(diff,progress)=output.take(child(g,extra)).map_err(|e|tag(e,extra))?.ok_or_else(invalid)?;*self.decision=Some(diff);output.begin_close();self.phase=14;p=add(progress,extra)?;},14=>{p=close_cursor(&mut self.output,g)?;if self.output.is_none(){self.outcome=Some(RowOutcome::Changed);self.phase=99;}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy singleton field")?;Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready()||self.decision.is_none(){return Err(invalid());}Ok(scalar(2*size_of::<Option<EnergyModelDiff>>()+1))}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(EnergyModelDiff,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None);}self.phase=100;Ok(Some((self.decision.take().ok_or_else(invalid)?,receipt(d))))}
 pub fn inverse_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.phase!=100||self.inverse.is_none(){return Err(invalid());}Ok(scalar(2*size_of::<Option<S::Scalar>>()+1))}
 pub fn take_inverse(&mut self,g:RetainedCloneGrant)->Result<Option<(S::Scalar,RetainedCloneProgress)>,ValueError>{let d=self.inverse_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None);}Ok(Some((self.inverse.take().ok_or_else(invalid)?,receipt(d))))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(c)=self.stage.as_mut(){c.begin_close();}if let Some(c)=self.output.as_mut(){c.begin_close();}}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if self.output.is_some(){return cursor_demand(&self.output,body);}if self.stage.is_some(){return cursor_demand(&self.stage,body);}if !self.retirement.is_empty()||self.decision.is_some(){return self.retirement.next_owner_demands::<EnergyModelDiff>(self.decision.is_some(),&None,body);}if self.branch.is_some(){return self.retirement.next_owner_demands::<SealedShared<S::Branch>>(true,&None,body);}if self.value.is_some()||self.inverse.is_some(){return Ok(scalar(4*size_of::<Option<S::Scalar>>()));}RetainedCloneBinding::close_demand(if self.original.is_some(){&self.original}else{&self.authored},body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}if self.output.is_some(){return close_cursor(&mut self.output,g).map(RetainedCloneStep::Progress);}if self.stage.is_some(){return close_cursor(&mut self.stage,g).map(RetainedCloneStep::Progress);}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.decision,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.branch,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}if self.value.is_some()||self.inverse.is_some(){*self.value=None;*self.inverse=None;return Ok(RetainedCloneStep::Progress(receipt(d)));}let step=RetainedCloneBinding::close_one(if self.original.is_some(){&mut self.original}else{&mut self.authored},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.stage.is_none()&&self.output.is_none()&&self.value.is_none()&&self.inverse.is_none()&&self.branch.is_none()&&self.decision.is_none()&&self.retirement.is_empty()&&self.original.is_none()&&self.authored.is_none()}
}
impl<S:SingleFieldPath> RowFieldPreparation for SingleFieldPreparation<S>{type Input=S::Scalar;type Inverse=S::Scalar;fn new()->Self{Self::new()}fn check(&self,v:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>)->Result<(),ValueError>{if key.is_some(){return Err(invalid());}Self::check(self,v,o)}fn demand(&self,v:RetainedCloneRef<'_,Self::Input>,_:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,b:usize)->Result<RetirementDemand,ValueError>{Self::demand(self,v,o,b)}fn advance(&mut self,v:RetainedCloneRef<'_,Self::Input>,_:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,b:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Self::advance(self,v,o,b,g)}fn ready(&self)->bool{Self::ready(self)}fn outcome(&self)->Option<RowOutcome>{Self::outcome(self)}fn take_demand(&self)->Result<RetirementDemand,ValueError>{Self::take_demand(self)}fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(EnergyModelDiff,RetainedCloneProgress)>,ValueError>{Self::take(self,g)}fn inverse_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Self::inverse_demand(self).map(|_|scalar(1))}fn prepare_inverse(&mut self,_:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=scalar(1);Ok(if retained_mutation_demand_fits(d,g){RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(Default::default())})}fn inverse_ready(&self)->bool{!self.closing&&self.phase==100&&self.inverse.is_some()}fn take_inverse_demand(&self)->Result<RetirementDemand,ValueError>{Self::inverse_demand(self)}fn take_inverse(&mut self,g:RetainedCloneGrant)->Result<Option<(Self::Inverse,RetainedCloneProgress)>,ValueError>{Self::take_inverse(self,g)}fn begin_close(&mut self){Self::begin_close(self)}fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{Self::close_demand(self,b)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Self::close_step(self,g)}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}}
impl<S:SingleFieldPath> Drop for SingleFieldPreparation<S>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"original singleton field retains candidate or inverse custody");if empty{unsafe{ManuallyDrop::drop(&mut self.value);ManuallyDrop::drop(&mut self.inverse);ManuallyDrop::drop(&mut self.branch);ManuallyDrop::drop(&mut self.decision);}}}}
